import fs from 'node:fs'
import path from 'node:path'

const files = {
  "package.json": "",
  "src/App.tsx": "",
  "src/lib/cloud.ts": "",
  "src/lib/iamCloud.ts": "",
  "src/lib/storage.ts": "",
  "src/views/IamManagement.css": "",
  "src/views/IamManagement.tsx": "",
  "src/views/Users.tsx": "",
  "supabase/functions/invite-user/index.ts": ""
}
const root = process.cwd()

if (!fs.existsSync(path.join(root, 'package.json')) || !fs.existsSync(path.join(root, 'src'))) {
  console.error('ERROR: Spustite instalator v koreni projektu vedla package.json a priecinka src.')
  process.exit(1)
}

const stamp = new Date().toISOString().replace(/[:.]/g, '-')
const backupRoot = path.join(root, `backup-before-v0122-fix4-${stamp}`)

for (const relative of Object.keys(files)) {
  const target = path.join(root, relative)
  if (fs.existsSync(target)) {
    const backup = path.join(backupRoot, relative)
    fs.mkdirSync(path.dirname(backup), { recursive: true })
    fs.copyFileSync(target, backup)
  }
}

for (const [relative, encoded] of Object.entries(files)) {
  const target = path.join(root, relative)
  fs.mkdirSync(path.dirname(target), { recursive: true })
  fs.writeFileSync(target, Buffer.from(encoded, 'base64'))
  console.log('OK:', relative)
}

for (const file of ['tsconfig.tsbuildinfo', 'tsconfig.app.tsbuildinfo', 'tsconfig.node.tsbuildinfo']) {
  const target = path.join(root, file)
  if (fs.existsSync(target)) fs.rmSync(target, { force: true })
}

const packageJson = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'))
const app = fs.readFileSync(path.join(root, 'src/App.tsx'), 'utf8')
const iamCloud = fs.readFileSync(path.join(root, 'src/lib/iamCloud.ts'), 'utf8')
const iamView = fs.readFileSync(path.join(root, 'src/views/IamManagement.tsx'), 'utf8')
const storage = fs.readFileSync(path.join(root, 'src/lib/storage.ts'), 'utf8')
const users = fs.readFileSync(path.join(root, 'src/views/Users.tsx'), 'utf8')
const edge = fs.readFileSync(path.join(root, 'supabase/functions/invite-user/index.ts'), 'utf8')

const checks = [
  ['version', packageJson.version === '0.12.2-fix.4'],
  ['storage version', storage.includes("CURRENT_VERSION = '0.12.2-fix.4'")],
  ['IAM cloud module', iamCloud.includes('export async function loadIamData')],
  ['IAM cloud import', app.includes("from './lib/iamCloud'")],
  ['IAM canConfigure prop', iamView.includes('canConfigure: boolean') && app.includes('canConfigure={canResolve}')],
  ['profile password modal', app.includes('AccountProfileModal') && app.includes('Môj profil a zmena hesla')],
  ['admin password UI', users.includes('AdminSetPasswordModal') && users.includes('Nastaviť nové heslo')],
  ['admin password server', edge.includes('updateUserById') && edge.includes("action === 'set-password'")],
]

for (const [name, ok] of checks) {
  console.log(ok ? 'VERIFIED:' : 'FAILED:', name)
  if (!ok) process.exitCode = 1
}

if (!process.exitCode) {
  console.log('VERIFIED: build fix 0.12.2-fix.4 je nainstalovany.')
  console.log('Potom spustite: npm run build')
}
